  if (S.song.rawNotes) S.song.rawNotes[S.selTrack].push({t: pp.t + S.chopS, d: pp.snap, p: pp.pitch, v: S.pencilVel, added});
  pushUndo({kind: "add", ti: S.selTrack, ni: tr.notes.length - 1});
