  if (delta > 0.16) return;
  const when = S.audio.currentTime + Math.max(0.005, delta);
  if (S.metLastWhen >= 0 && Math.abs(when - S.metLastWhen) < 0.03) return; // this beat is scheduled
  S.metLastWhen = when;
  const k = Math.round(bt / tb);
