    const items = selEditItems();
    if (!items.length) return;
    if (!velSnap) velSnap = items.map(({ti, ni, n}) => ({ti, ni, t: n.t, d: n.d, p: n.p, v: n.v}));
    for (const it of items) it.n.v = v;
