    if (S.song.tracks.some((_, ti) => trackIsDrums(ti))) addOpt(f, "drums", "drums (kick)");
    S.song.tracks.forEach((tr2, ti) => { if (!trackIsDrums(ti)) addOpt(f, "t" + ti, tr2.name || "track " + (ti + 1)); });
    addOpt(f, "chords", "chords");
