    const tsel = document.getElementById("bstarget");
    tsel.innerHTML = "";
    S.song.tracks.forEach((tr2, ti) => { if (!trackIsDrums(ti)) addOpt(tsel, String(ti), tr2.name || "track " + (ti + 1)); });
    addOpt(tsel, "new", "＋ new bass track");
